function setSelect(sel,v,t){sel.innerHTML='<option value="0">'+(sel===selB?'Marka Seçiniz':'Model Seçiniz')+'</option>'+(v?'<option value="'+v+'" selected>'+esc(t)+'</option>':'');sel.value=v?String(v):'0';}
